tool_input.command:
$ErrorActionPreference = 'SilentlyContinue'
$githubPath = "/home/author\Documents\GitHub"

Write-Host "=== CLEANING BUILD ARTIFACTS ===" 

# Remove FTCHome node_modules
$ftcPath = "$githubPath\FTCHome\node_modules"
if (Test-Path $ftcPath) {
  Write-Host "Removing FTCHome/node_modules..."
  try {
    Remove-Item -Path $ftcPath -Recurse -Force -ErrorAction Stop
    Write-Host "Deleted successfully."
  } catch {
    Write-Host "Error: $_"
  }
}

# Clean individual target directories with proper paths
$projects = Get-ChildItem -Path $githubPath -Directory -Force
foreach ($proj in $projects) {
  $targetPath = "$($proj.FullName)\target"
  if (Test-Path $targetPath) {
    $size = (Get-ChildItem -Path $targetPath -Recurse -File -Force | Measure-Object -Property Length -Sum).Sum
    $sizeMB = [math]::Round($size / 1MB, 2)
    if ($sizeMB -gt 1) {
      Write-Host "Removing $($proj.Name)\target ($sizeMB MB)..."
      try {
        Remove-Item -Path $targetPath -Recurse -Force -ErrorAction Stop
        Write-Host "  Deleted."
      } catch {
        Write-Host "  Error: $_"
      }
    }
  }
}

Write-Host ""
Write-Host "=== DISK SPACE AFTER CLEANUP ===" 
Get-Volume | Where-Object { $_.DriveLetter -eq 'C' } | ForEach-Object {
  $total = [math]::Round($_.Size / 1GB, 2)
  $free = [math]::Round($_.SizeRemaining / 1GB, 2)
  $used = $total - $free
  $percent = [math]::Round(($used / $total) * 100, 1)
  Write-Host "Drive C: $used GB / $total GB used ($percent%) - $free GB free"
}
